#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    while(n--){
        int s, p; cin >> s >> p;
        vector<double> x(p), y(p);
        for (int i=0;i<p;i++) cin >> x[i] >> y[i];
        vector<double> dist(p, 1e18);
        vector<bool> inMst(p,false);
        dist[0]=0;
        vector<double> mstEdges;
        for (int iter=0; iter<p; iter++){
            int u=-1;
            for (int i=0;i<p;i++) if(!inMst[i] && (u==-1 || dist[i]<dist[u])) u=i;
            inMst[u]=true;
            if (dist[u] < 1e17) mstEdges.push_back(dist[u]);
            for (int v=0;v<p;v++) if(!inMst[v]){
                double d = hypot(x[u]-x[v], y[u]-y[v]);
                if (d < dist[v]) dist[v]=d;
            }
        }
        sort(mstEdges.rbegin(), mstEdges.rend());
        double ans = 0;
        if (s-1 < (int)mstEdges.size()) ans = mstEdges[s-1];
        printf("%.2f\n", ans);
    }
}

